package transpose

import "strings"

// Transpose returns the input text with its rows and columns swapped.
//
// When the input rows have different lengths, the output is padded with
// spaces on the left but never on the right: a space that is a real
// character of the input is preserved, while padding spaces added because
// a row is shorter than a given column are trimmed from the right end of
// the corresponding output row.
func Transpose(input []string) []string {
	var maxLen int
	rows := make([][]rune, len(input))
	for i, row := range input {
		rows[i] = []rune(row)
		if len(rows[i]) > maxLen {
			maxLen = len(rows[i])
		}
	}

	result := make([]string, 0, maxLen)
	for j := 0; j < maxLen; j++ {
		// lastReal is the index of the bottom-most input row that holds a
		// real character in column j. Rows below it would only contribute
		// padding spaces, which we must not emit on the right.
		lastReal := -1
		for i, r := range rows {
			if j < len(r) {
				lastReal = i
			}
		}

		var b strings.Builder
		for i := 0; i <= lastReal; i++ {
			if j < len(rows[i]) {
				b.WriteRune(rows[i][j])
			} else {
				b.WriteRune(' ')
			}
		}
		result = append(result, b.String())
	}
	return result
}

